package in.kabadiwala.connect.service; import in.kabadiwala.connect.model.Notification; import in.kabadiwala.connect.repository.NotificationRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import java.util.Map; @Service public class NotificationService {private final NotificationRepository r; public NotificationService(NotificationRepository r){this.r=r;} public void send(String uid,String type,String entityType,String entityId,Map<String,Object> params){var n=new Notification();n.userId=uid;n.type=type;n.titleKey="notification."+type+".title";n.messageKey="notification."+type+".message";n.entityType=entityType;n.entityId=entityId;n.params=params;r.save(n);} public Page<Notification> list(String uid,int page,int size){return r.findByUserIdOrderByCreatedAtDesc(uid,PageRequest.of(page,Math.min(size,50)));} public void read(String uid,String id){var n=r.findById(id).orElseThrow();if(!n.userId.equals(uid))throw new IllegalArgumentException("Access denied");n.read=true;r.save(n);} public void readAll(String uid){var xs=r.findByUserIdAndReadFalse(uid);xs.forEach(n->n.read=true);r.saveAll(xs);} public long unread(String uid){return r.countByUserIdAndReadFalse(uid);}}
